CREATE TABLE IF NOT EXISTS report_deliveries (id INTEGER PRIMARY KEY AUTOINCREMENT,report_date TEXT NOT NULL,report_type TEXT NOT NULL,recipient_hash TEXT NOT NULL,subject TEXT NOT NULL,status TEXT NOT NULL,provider_message_id TEXT,attempt_count INTEGER NOT NULL DEFAULT 0,last_error TEXT,sent_at TEXT,created_at TEXT NOT NULL,UNIQUE(report_date,report_type,recipient_hash));
CREATE TABLE IF NOT EXISTS report_archives (id INTEGER PRIMARY KEY AUTOINCREMENT,report_date TEXT NOT NULL,report_type TEXT NOT NULL,html_path TEXT NOT NULL,content_sha256 TEXT NOT NULL,generated_at TEXT NOT NULL,UNIQUE(report_date,report_type));
